-- 油谷坑战斗遗址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-油谷坑战斗遗址-1784570533785', 'archive', 'revolution', '[]', 'published', '油谷坑战斗遗址', '油谷坑战斗遗址位于河源市紫金县苏区镇赤溪村油谷坑。1933年2月27日，红一团行军至狗头嶂时，与国民党军罗克士残部遭遇。3月27日，红一团移驻黄塘埔美三板桥、塘肚一带，并与紫河特区蓝黄区委书记钟子怀接上了头，得知马毅营和罗克士残部准备进剿埔美，认为周围地形不利于红军作战，随向黄塘曹坑、拔寨转移。马毅营尾随红一团至曹坑。并连续5次发起冲锋，但均被击退。虽大量杀伤国民党军，但红军也伤亡惨重。为减少伤亡', 'normal', '[]', 'version-archive-doc-油谷坑战斗遗址-1784570533785-1', 'version-archive-doc-油谷坑战斗遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
