VALUES ('content-archive-doc-红军兵工厂旧址-1784570533785', 'archive', 'revolution', '[]', 'published', '红军兵工厂旧址', '红军兵工厂旧址位于苏区镇炮子村，是一座民房，建于清代，坐北向南，二间二进，右侧横屋，左侧只建横屋厅，檩条山墙结构，硬山顶，砖墙，石基脚，建筑面积110多平方米。2009年4月被紫金县人民政府公布为紫金县文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为广东省爱国主义教育基地。', 'normal', '[]', 'version-archive-doc-红军兵工厂旧址-1784570533785-1', 'version-archive-doc-红军兵工厂旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
