-- 红六军四十九团团部旧址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-红六军四十九团团部旧址-1784570533785', 'archive', 'revolution', '[]', 'published', '红六军四十九团团部旧址', '红六军四十九团团部旧址和中共紫河特区委、共青团紫河特区委、紫河游击队队部成立旧址位于苏区镇炮子村红旗小组明德楼。 1929年3月，蒋桂战争爆发后，很快桂系为蒋介石所败，桂系李济深在广东的统治也为蒋系陈济棠所取代，接着发生蒋、阎、冯军阀混战。4月，海陆丰的驻军十六师全部调走，海陆丰的反动势力顿显薄弱，反动派非常恐慌。9月，海陆惠紫特委在省委领导下，认识到革命高潮已经到来，便不失时机地决定建立红军。1', 'normal', '[]', 'version-archive-doc-红六军四十九团团部旧址-1784570533785-1', 'version-archive-doc-红六军四十九团团部旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-红六军四十九团团部旧址-1784570533785-1', 'content-archive-doc-红六军四十九团团部旧址-1784570533785', 1, '红六军四十九团团部旧址', '红六军四十九团团部旧址和中共紫河特区委、共青团紫河特区委、紫河游击队队部成立旧址位于苏区镇炮子村红旗小组明德楼。 1929年3月，蒋桂战争爆发后，很快桂系为蒋介石所败，桂系李济深在广东的统治也为蒋系陈济棠所取代，接着发生蒋、阎、冯军阀混战。4月，海陆丰的驻军十六师全部调走，海陆丰的反动势力顿显薄弱，反动派非常恐慌。9月，海陆惠紫特委在省委领导下，认识到革命高潮已经到来，便不失时机地决定建立红军。1', '红六军四十九团团部旧址和中共紫河特区委、共青团紫河特区委、紫河游击队队部成立旧址位于苏区镇炮子村红旗小组明德楼。 1929年3月，蒋桂战争爆发后，很快桂系为蒋介石所败，桂系李济深在广东的统治也为蒋系陈济棠所取代，接着发生蒋、阎、冯军阀混战。4月，海陆丰的驻军十六师全部调走，海陆丰的反动势力顿显薄弱，反动派非常恐慌。9月，海陆惠紫特委在省委领导下，认识到革命高潮已经到来，便不失时机地决定建立红军。10月初，海陆惠紫特委在黄羌朝面山蔡背窝举行军事会议。会后，在朝面山大路下村召开大会，宣告中国工农红军第六军第十七师四十九团成立。不久，四十九团团部迁到苏区镇炮子村红旗小组明德楼。虽然当时只有100多人', '{"archiveType":"revolution","type":"revolution","year":1929,"longitude":115.342,"latitude":23.361,"address":"苏区镇炮子村红旗小组明德楼","coverImage":"/images/archives/red-49th-regiment-hq.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/red-49th-regiment-hq.jpeg","caption":"红六军四十九团团部旧址"}]}', 'system', 1784570533785);

