-- 炮子乡农会旧址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-炮子乡农会旧址-1784570533785', 'archive', 'government', '[]', 'published', '炮子乡农会旧址', '炮子乡农会、紫金县总农会旧址建于民国期间，坐北向南，三间二进二层，檩条山墙结构。硬山顶，平脊，灰瓦，砖墙，石基脚。占地面积约65平方米。1923年1月，苏区山子背人张子玉受彭湃指派，带着2000份农会证返回苏区，3月成立了炮子乡农会，张子玉为会长，钟乐善、黄培先为副会长，隶属海丰总农会领导，从此点燃了紫金农民运动的火种。同年7月，紫金各乡农民代表在此集会，成立紫金县总农会和龙窝区农会。炮子乡农会、', 'normal', '[]', 'version-archive-doc-炮子乡农会旧址-1784570533785-1', 'version-archive-doc-炮子乡农会旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-炮子乡农会旧址-1784570533785-1', 'content-archive-doc-炮子乡农会旧址-1784570533785', 1, '炮子乡农会旧址', '炮子乡农会、紫金县总农会旧址建于民国期间，坐北向南，三间二进二层，檩条山墙结构。硬山顶，平脊，灰瓦，砖墙，石基脚。占地面积约65平方米。1923年1月，苏区山子背人张子玉受彭湃指派，带着2000份农会证返回苏区，3月成立了炮子乡农会，张子玉为会长，钟乐善、黄培先为副会长，隶属海丰总农会领导，从此点燃了紫金农民运动的火种。同年7月，紫金各乡农民代表在此集会，成立紫金县总农会和龙窝区农会。炮子乡农会、', '炮子乡农会、紫金县总农会旧址建于民国期间，坐北向南，三间二进二层，檩条山墙结构。硬山顶，平脊，灰瓦，砖墙，石基脚。占地面积约65平方米。1923年1月，苏区山子背人张子玉受彭湃指派，带着2000份农会证返回苏区，3月成立了炮子乡农会，张子玉为会长，钟乐善、黄培先为副会长，隶属海丰总农会领导，从此点燃了紫金农民运动的火种。同年7月，紫金各乡农民代表在此集会，成立紫金县总农会和龙窝区农会。炮子乡农会、紫金县总农会旧址于2009年4月被紫金县人民政府公布为紫金县文物保护单位；2011年3月被河源市人民政府公布为河源市重点文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为', '{"archiveType":"government","type":"government","year":1923,"longitude":115.3445,"latitude":23.3605,"address":"炮子村","coverImage":"","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[]}', 'system', 1784570533785);

-- 战壕遗址
