VALUES ('content-archive-doc-战壕遗址-1784570533785', 'archive', 'revolution', '[]', 'published', '战壕遗址', '战壕遗址位于河源市紫金县苏区镇炮子村伯公坳。1928年3月，国民党第十一军某部3000余人，由五华县安流出发，经紫金洋头、慎田进剿龙炮苏区。中共紫金县委、县苏维埃政府与红二师研究后，决定组织正规军、地方团队和区、乡赤卫队进行保卫苏维埃的战斗。苏区 军民紧张地在各战略要地构筑防御阵地，其中在伯公坳挖战壕，修掩体，誓死保卫苏区。现存战壕东西走向，长56米，宽', 'normal', '[]', 'version-archive-doc-战壕遗址-1784570533785-1', 'version-archive-doc-战壕遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-战壕遗址-1784570533785-1', 'content-archive-doc-战壕遗址-1784570533785', 1, '战壕遗址', '战壕遗址位于河源市紫金县苏区镇炮子村伯公坳。1928年3月，国民党第十一军某部3000余人，由五华县安流出发，经紫金洋头、慎田进剿龙炮苏区。中共紫金县委、县苏维埃政府与红二师研究后，决定组织正规军、地方团队和区、乡赤卫队进行保卫苏维埃的战斗。苏区 军民紧张地在各战略要地构筑防御阵地，其中在伯公坳挖战壕，修掩体，誓死保卫苏区。现存战壕东西走向，长56米，宽', '战壕遗址位于河源市紫金县苏区镇炮子村伯公坳。1928年3月，国民党第十一军某部3000余人，由五华县安流出发，经紫金洋头、慎田进剿龙炮苏区。中共紫金县委、县苏维埃政府与红二师研究后，决定组织正规军、地方团队和区、乡赤卫队进行保卫苏维埃的战斗。苏区 军民紧张地在各战略要地构筑防御阵地，其中在伯公坳挖战壕，修掩体，誓死保卫苏区。现存战壕东西走向，长56米，宽', '{"archiveType":"revolution","type":"revolution","year":1928,"longitude":115.333,"latitude":23.3585,"address":"河源市紫金县苏区镇炮子村伯公坳","coverImage":"/images/archives/trench-site_1.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/trench-site_1.jpeg","caption":"战壕遗址"},{"type":"image","url":"/images/archives/trench-site_2.jpeg","caption":"战壕遗址"}]}', 'system', 1784570533785);

-- 张子玉烈士纪念碑
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-张子玉烈士纪念碑-1784570533785', 'archive', 'revolution', '[]', 'published', '张子玉烈士纪念碑', '张子玉烈士纪念碑位于紫金县苏区镇炮子村锡山小学操场边。张子玉（1899—1928年），1923年由他发起成立紫金县第一个农会——炮子乡农会并任会长，1925年加入中国共产党，1927年组织紫金南路农民自卫军参加“四·二六”暴动，1928年3月在陆丰罗畲突围中与部队失去联系，回炮子召集人员，迅速恢复苏区革命斗争，指挥赤卫队员坚持游击活动，同年8月因叛徒出卖被捕，10月被杀害，时年29岁。1977年，', 'normal', '[]', 'version-archive-doc-张子玉烈士纪念碑-1784570533785-1', 'version-archive-doc-张子玉烈士纪念碑-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-张子玉烈士纪念碑-1784570533785-1', 'content-archive-doc-张子玉烈士纪念碑-1784570533785', 1, '张子玉烈士纪念碑', '张子玉烈士纪念碑位于紫金县苏区镇炮子村锡山小学操场边。张子玉（1899—1928年），1923年由他发起成立紫金县第一个农会——炮子乡农会并任会长，1925年加入中国共产党，1927年组织紫金南路农民自卫军参加“四·二六”暴动，1928年3月在陆丰罗畲突围中与部队失去联系，回炮子召集人员，迅速恢复苏区革命斗争，指挥赤卫队员坚持游击活动，同年8月因叛徒出卖被捕，10月被杀害，时年29岁。1977年，', '张子玉烈士纪念碑位于紫金县苏区镇炮子村锡山小学操场边。张子玉（1899—1928年），1923年由他发起成立紫金县第一个农会——炮子乡农会并任会长，1925年加入中国共产党，1927年组织紫金南路农民自卫军参加“四·二六”暴动，1928年3月在陆丰罗畲突围中与部队失去联系，回炮子召集人员，迅速恢复苏区革命斗争，指挥赤卫队员坚持游击活动，同年8月因叛徒出卖被捕，10月被杀害，时年29岁。1977年，紫金县人民政府兴建张子玉烈士纪念碑一座，以彰显张子玉烈士的丰功伟绩，告慰英魂。2011年重建，碑身青砖垒砌，外贴白瓷片，高', '{"archiveType":"revolution","type":"revolution","year":1928,"longitude":115.339,"latitude":23.356,"address":"紫金县苏区镇炮子村锡山小学操场边","coverImage":"/images/archives/zhangziyu-martyr-monument_1.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zhangziyu-martyr-monument_1.jpeg","caption":"张子玉烈士纪念碑"},{"type":"image","url":"/images/archives/zhangziyu-martyr-monument_2.jpeg","caption":"张子玉烈士纪念碑"}]}', 'system', 1784570533785);

-- 中国工农革命军第二师师部旧址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-中国工农革命军第二师师部旧址-1784570533785', 'archive', 'revolution', '[]', 'published', '中国工农革命军第二师师部旧址', '位于苏区镇炮子村，建于清末，建筑面积300多平方米。1927年10月，撤退到海陆惠紫的“八一”南昌起义部分队伍，在中共东江特委的领导下，整编为中国工农革命军第二师（红二师）。同月，红二师进驻紫金，师部和党代表办公地设在炮子福星楼。师长董朗、党代表颜昌颐，在这里指挥武装斗争，给反革命武装以沉重的打击。1928年3月，因国民党反动派派重兵“围剿”，红二师与赤卫队一起保卫紫金县委、紫金县苏维埃政府和人民', 'normal', '[]', 'version-archive-doc-中国工农革命军第二师师部旧址-1784570533785-1', 'version-archive-doc-中国工农革命军第二师师部旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-中国工农革命军第二师师部旧址-1784570533785-1', 'content-archive-doc-中国工农革命军第二师师部旧址-1784570533785', 1, '中国工农革命军第二师师部旧址', '位于苏区镇炮子村，建于清末，建筑面积300多平方米。1927年10月，撤退到海陆惠紫的“八一”南昌起义部分队伍，在中共东江特委的领导下，整编为中国工农革命军第二师（红二师）。同月，红二师进驻紫金，师部和党代表办公地设在炮子福星楼。师长董朗、党代表颜昌颐，在这里指挥武装斗争，给反革命武装以沉重的打击。1928年3月，因国民党反动派派重兵“围剿”，红二师与赤卫队一起保卫紫金县委、紫金县苏维埃政府和人民', '位于苏区镇炮子村，建于清末，建筑面积300多平方米。1927年10月，撤退到海陆惠紫的“八一”南昌起义部分队伍，在中共东江特委的领导下，整编为中国工农革命军第二师（红二师）。同月，红二师进驻紫金，师部和党代表办公地设在炮子福星楼。师长董朗、党代表颜昌颐，在这里指挥武装斗争，给反革命武装以沉重的打击。1928年3月，因国民党反动派派重兵“围剿”，红二师与赤卫队一起保卫紫金县委、紫金县苏维埃政府和人民群众撤出炮子，安全转移。后在海、陆、惠、紫、五等县坚持开展游击战争，多次粉碎国民党反动派的“围剿”，为保卫革命根据地作出了巨大贡献。1977年1月被紫金县人民政府公布为紫金县重点文物保护单位；2011', '{"archiveType":"revolution","type":"revolution","year":1927,"longitude":115.341,"latitude":23.3615,"address":"苏区镇炮子村","coverImage":"/images/archives/red-second-division-hq.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/red-second-division-hq.jpeg","caption":"中国工农革命军第二师师部旧址"}]}', 'system', 1784570533785);

