-- 紫金县老苏区革命烈士纪念堂
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-紫金县老苏区革命烈士纪念堂-1784570533785', 'archive', 'revolution', '[]', 'published', '紫金县老苏区革命烈士纪念堂', '紫金县老苏区革命烈士纪念堂位于河源市紫金县苏区镇炮子村，1927年4月 26日，在东江特委的领导下，在刘琴西等人的直接指挥下，紫金人民成功进行了“四二六” 武装暴动，占领了紫金县城。5月1日，成立了紫金县人民政府，刘琴西为主席，戴耀田为副主席，同时成立了以刘琴西为总指挥的紫金县工农革命军总指挥部。5月8日，紫金县党政军机关转移到紫金南部地区，在炮子建立革命根据地，开展土地革命斗争。此后，中共紫金县', 'normal', '[]', 'version-archive-doc-紫金县老苏区革命烈士纪念堂-1784570533785-1', 'version-archive-doc-紫金县老苏区革命烈士纪念堂-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-紫金县老苏区革命烈士纪念堂-1784570533785-1', 'content-archive-doc-紫金县老苏区革命烈士纪念堂-1784570533785', 1, '紫金县老苏区革命烈士纪念堂', '紫金县老苏区革命烈士纪念堂位于河源市紫金县苏区镇炮子村，1927年4月 26日，在东江特委的领导下，在刘琴西等人的直接指挥下，紫金人民成功进行了“四二六” 武装暴动，占领了紫金县城。5月1日，成立了紫金县人民政府，刘琴西为主席，戴耀田为副主席，同时成立了以刘琴西为总指挥的紫金县工农革命军总指挥部。5月8日，紫金县党政军机关转移到紫金南部地区，在炮子建立革命根据地，开展土地革命斗争。此后，中共紫金县', '紫金县老苏区革命烈士纪念堂位于河源市紫金县苏区镇炮子村，1927年4月 26日，在东江特委的领导下，在刘琴西等人的直接指挥下，紫金人民成功进行了“四二六” 武装暴动，占领了紫金县城。5月1日，成立了紫金县人民政府，刘琴西为主席，戴耀田为副主席，同时成立了以刘琴西为总指挥的紫金县工农革命军总指挥部。5月8日，紫金县党政军机关转移到紫金南部地区，在炮子建立革命根据地，开展土地革命斗争。此后，中共紫金县委、县苏维埃政府在苏区领导紫金人民进行轰轰烈烈的土地革命、根据地建设和武装斗争，经历了炮子三次反“围剿”、苏区保卫战等众多惨烈的战斗。苏区人民为建设和保卫革命根据地作出了巨大贡献和重大牺牲。1963年', '{"archiveType":"revolution","type":"revolution","year":1927,"longitude":115.342,"latitude":23.362,"address":"河源市紫金县苏区镇炮子村","coverImage":"/images/archives/zijin-old-suqu-martyrs-memorial_1.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zijin-old-suqu-martyrs-memorial_1.jpeg","caption":"紫金县老苏区革命烈士纪念堂"},{"type":"image","url":"/images/archives/zijin-old-suqu-martyrs-memorial_2.jpeg","caption":"紫金县老苏区革命烈士纪念堂"}]}', 'system', 1784570533785);

-- 红二、四师联合公审大会遗址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-红二四师联合公审大会遗址-1784570533785', 'archive', 'revolution', '[]', 'published', '红二、四师联合公审大会遗址', '红二、四师联合公审大会遗址位于河源市紫金县苏区镇炮子村。1927年12月，撤向东江地区的广州起义部队1000多人，在县改编为中国工农革命军第四师（简称红四师），叶镛为师长，宋湘涛为副师长，袁裕为师参谋长。1928年1月，红四师智取紫金县城，活捉国民党紫金县长东丘国忠等17名反动头子。3日，在湖子仓研究决定于5日召开公审大会，处决丘国忠等17名反动分子。5日上午，赤卫队和红军战士把丘国忠等反动头子押', 'normal', '[]', 'version-archive-doc-红二四师联合公审大会遗址-1784570533785-1', 'version-archive-doc-红二四师联合公审大会遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-红二四师联合公审大会遗址-1784570533785-1', 'content-archive-doc-红二四师联合公审大会遗址-1784570533785', 1, '红二、四师联合公审大会遗址', '红二、四师联合公审大会遗址位于河源市紫金县苏区镇炮子村。1927年12月，撤向东江地区的广州起义部队1000多人，在县改编为中国工农革命军第四师（简称红四师），叶镛为师长，宋湘涛为副师长，袁裕为师参谋长。1928年1月，红四师智取紫金县城，活捉国民党紫金县长东丘国忠等17名反动头子。3日，在湖子仓研究决定于5日召开公审大会，处决丘国忠等17名反动分子。5日上午，赤卫队和红军战士把丘国忠等反动头子押', '红二、四师联合公审大会遗址位于河源市紫金县苏区镇炮子村。1927年12月，撤向东江地区的广州起义部队1000多人，在县改编为中国工农革命军第四师（简称红四师），叶镛为师长，宋湘涛为副师长，袁裕为师参谋长。1928年1月，红四师智取紫金县城，活捉国民党紫金县长东丘国忠等17名反动头子。3日，在湖子仓研究决定于5日召开公审大会，处决丘国忠等17名反动分子。5日上午，赤卫队和红军战士把丘国忠等反动头子押赴刑场，由钟佑廷、钟初发、温冠雄等用马刀处决这批反动分子。群众振臂欢呼，扬眉吐气，都说苏维埃政权够气派，工农红军确威风，炮子革命根据地沉浸在一片欢乐之中。遗址现为苏区中学操场。', '{"archiveType":"revolution","type":"revolution","year":1927,"longitude":115.338,"latitude":23.36,"address":"河源市紫金县苏区镇炮子村","coverImage":"/images/archives/red-2nd-4th-division-trial.png","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/red-2nd-4th-division-trial.png","caption":"红二、四师联合公审大会遗址"}]}', 'system', 1784570533785);

-- 炮子农民自卫队队部遗址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-炮子农民自卫队队部遗址-1784570533785', 'archive', 'government', '[]', 'published', '炮子农民自卫队队部遗址', '位于河源市紫金县苏区镇炮子村。1923年1月，陈炯明叛变孙中山民主革命盘踞东江后，豢养了一批亲信，为非作歹。一次，其部在紫金龙窝、炮子等地横行霸道，打家劫舍，抢走钟善道、钟彩文的马。族中头领钟乐善，凭借拥有10多人枪的队伍，下令抄小路在赤溪截击，打败了陈炯明部。陈炯明得知后，即下令“剿平”炮子。民众在危急之时，一筹莫展。张子玉顺水推舟，说明要粉碎陈炯明“剿平”炮子的阴谋，必须在彭海的领导下，成立农', 'normal', '[]', 'version-archive-doc-炮子农民自卫队队部遗址-1784570533785-1', 'version-archive-doc-炮子农民自卫队队部遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
