VALUES ('version-archive-doc-洋磜反围剿战斗遗址-1784570533785-1', 'content-archive-doc-洋磜反围剿战斗遗址-1784570533785', 1, '洋磜反“围剿”战斗遗址', '洋磜反“围剿”战斗遗址位于河源市紫金县苏区镇炮子村锡山洋磜。1931年10月，南岭反动分子、五县联防剿共主任钟汉平率南岭、登峯、大茂、禾多布、黄布、小北等48个乡的民团，并勾结国民党军驻炮子叶吉辉一个营、驻永坑一个营、土匪叶添等杂牌军共3000余人从锡山崬、油谷坑、唱歌崬等地登山，围剿洋磜，企图消灭隐藏在洋磜坚持游击战争的红十一军军事部，海陆紫县苏，紫金县委、县苏领导机关。在敌强我弱的情况下，古大', '洋磜反“围剿”战斗遗址位于河源市紫金县苏区镇炮子村锡山洋磜。1931年10月，南岭反动分子、五县联防剿共主任钟汉平率南岭、登峯、大茂、禾多布、黄布、小北等48个乡的民团，并勾结国民党军驻炮子叶吉辉一个营、驻永坑一个营、土匪叶添等杂牌军共3000余人从锡山崬、油谷坑、唱歌崬等地登山，围剿洋磜，企图消灭隐藏在洋磜坚持游击战争的红十一军军事部，海陆紫县苏，紫金县委、县苏领导机关。在敌强我弱的情况下，古大存、古宜权召集海陆紫县苏主席团钟一强、林潭吉，紫金县委、龙炮区联队领导人戴耀田、缪冠儒等紧急会商并制定了反“围剿”的作战方案。永坑乡赤卫队70余人，在中队长高镜率领下，奋起迎战。梅兴乡赤卫队20余人，', '{"archiveType":"revolution","type":"revolution","year":1931,"longitude":115.344,"latitude":23.355,"address":"河源市紫金县苏区镇炮子村锡山洋磜","coverImage":"/images/archives/yangqi-anti-encirclement.png","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/yangqi-anti-encirclement.png","caption":"洋磜反“围剿”战斗遗址"}]}', 'system', 1784570533785);

-- 洋磜会师遗址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-洋磜会师遗址-1784570533785', 'archive', 'revolution', '[]', 'published', '洋磜会师遗址', '位于苏区镇炮子村锡山，在锡山崬、唱歌崬、峰的夹谷中，西连炮子的油谷坑，峭壁挺立，地势险要。山谷中有几座房屋，住着十来户人家。从1928年革命低潮以来，县委、县苏的领导机关经常来这里隐蔽，继续领导革命。1931年6月，海陆紫县苏、紫金县委、县苏领导机关又从风隆山搬到这里。八乡山是东江地区的重要革命根据地之一。1929年秋后，中共东江特委迁驻八乡山。八乡山便成为东江革命根据地的指挥中心。1931年1月', 'normal', '[]', 'version-archive-doc-洋磜会师遗址-1784570533785-1', 'version-archive-doc-洋磜会师遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-洋磜会师遗址-1784570533785-1', 'content-archive-doc-洋磜会师遗址-1784570533785', 1, '洋磜会师遗址', '位于苏区镇炮子村锡山，在锡山崬、唱歌崬、峰的夹谷中，西连炮子的油谷坑，峭壁挺立，地势险要。山谷中有几座房屋，住着十来户人家。从1928年革命低潮以来，县委、县苏的领导机关经常来这里隐蔽，继续领导革命。1931年6月，海陆紫县苏、紫金县委、县苏领导机关又从风隆山搬到这里。八乡山是东江地区的重要革命根据地之一。1929年秋后，中共东江特委迁驻八乡山。八乡山便成为东江革命根据地的指挥中心。1931年1月', '位于苏区镇炮子村锡山，在锡山崬、唱歌崬、峰的夹谷中，西连炮子的油谷坑，峭壁挺立，地势险要。山谷中有几座房屋，住着十来户人家。从1928年革命低潮以来，县委、县苏的领导机关经常来这里隐蔽，继续领导革命。1931年6月，海陆紫县苏、紫金县委、县苏领导机关又从风隆山搬到这里。八乡山是东江地区的重要革命根据地之一。1929年秋后，中共东江特委迁驻八乡山。八乡山便成为东江革命根据地的指挥中心。1931年1月，为配合蒋介石对中央根据地发起的第二次“围剿”，陈济棠调该军第二独立旅张瑞贵部到东江，纠集五华、丰顺、揭阳三县警卫队、民团、大规模向八乡山根据地发起“围剿”。面对恶劣环境，为保存实力，牵制敌人，红十一', '{"archiveType":"revolution","type":"revolution","year":1928,"longitude":115.345,"latitude":23.354,"address":"苏区镇炮子村锡山","coverImage":"/images/archives/yangqi-joining-forces.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/yangqi-joining-forces.jpeg","caption":"洋磜会师遗址"}]}', 'system', 1784570533785);

-- 云谭村农会旧址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-云谭村农会旧址-1784570533785', 'archive', 'revolution', '[]', 'published', '云谭村农会旧址', '位于河源市紫金县苏区镇炮子村山子背。1922年7月，彭湃领导成立6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰挑担度日的炮子村山子背农民张子玉，亲眼看到农会是为农民谋利益的组织，毅然参加了赤山约农会。彭湃得知张子玉是紫金县人，便在得趣书院接见了张子玉。1923年1月，张子玉受彭湃的委托，带着2000份农会证返回家', 'normal', '[]', 'version-archive-doc-云谭村农会旧址-1784570533785-1', 'version-archive-doc-云谭村农会旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-云谭村农会旧址-1784570533785-1', 'content-archive-doc-云谭村农会旧址-1784570533785', 1, '云谭村农会旧址', '位于河源市紫金县苏区镇炮子村山子背。1922年7月，彭湃领导成立6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰挑担度日的炮子村山子背农民张子玉，亲眼看到农会是为农民谋利益的组织，毅然参加了赤山约农会。彭湃得知张子玉是紫金县人，便在得趣书院接见了张子玉。1923年1月，张子玉受彭湃的委托，带着2000份农会证返回家', '位于河源市紫金县苏区镇炮子村山子背。1922年7月，彭湃领导成立6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰挑担度日的炮子村山子背农民张子玉，亲眼看到农会是为农民谋利益的组织，毅然参加了赤山约农会。彭湃得知张子玉是紫金县人，便在得趣书院接见了张子玉。1923年1月，张子玉受彭湃的委托，带着2000份农会证返回家乡，组建农会组织。张子玉回到家乡后，考虑到自己地位低下，难于开展工作，便向族中有威信的堂叔张大经讨教。张大经对张子玉的行动表示支持。于是商定在春节祭祖时，与族长商议。农历正月十四日（族人规定的“上丁日', '{"archiveType":"revolution","type":"revolution","year":1922,"longitude":115.336,"latitude":23.357,"address":"河源市紫金县苏区镇炮子村山子背","coverImage":"/images/archives/yuntan-farmers-association.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/yuntan-farmers-association.jpeg","caption":"云谭村农会旧址"}]}', 'system', 1784570533785);

