VALUES ('version-archive-doc-张子玉故居-1784570533785-1', 'content-archive-doc-张子玉故居-1784570533785', 1, '张子玉故居', '张子玉故居，位于河源市紫金县苏区镇炮子村山子背。张子玉（1899-1928），原名连科，出生于紫金县苏区镇炮子村一个雇农家庭。1922年逃难到海丰参加海丰县农会组织。后受彭湃派遣回乡发展农会。1923年农历正月十四日，发动组建紫金县第一个村农会－－云潭村农会。3月，发动建立紫金县第一个乡农会－－炮子乡农会，任会长。7月，协助钟一强等在炮子召开各乡农民代表会，成立紫金县总农会和龙窝区农会，并任龙窝区', '张子玉故居，位于河源市紫金县苏区镇炮子村山子背。张子玉（1899-1928），原名连科，出生于紫金县苏区镇炮子村一个雇农家庭。1922年逃难到海丰参加海丰县农会组织。后受彭湃派遣回乡发展农会。1923年农历正月十四日，发动组建紫金县第一个村农会－－云潭村农会。3月，发动建立紫金县第一个乡农会－－炮子乡农会，任会长。7月，协助钟一强等在炮子召开各乡农民代表会，成立紫金县总农会和龙窝区农会，并任龙窝区农会会长。不久，在龙窝区组建农民自卫军。1925年，紫金县总农会改称紫金县农民协会，任第三区农民协会会长。同年加入中国共产党。1927年，参与组织南路农民自卫军参加紫金县“四二六”武装暴动，12月，把', '{"archiveType":"revolution","type":"revolution","year":1922,"longitude":115.339,"latitude":23.356,"address":"河源市紫金县苏区镇炮子村山子背","coverImage":"/images/archives/zhangziyu-former-residence_1.png","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zhangziyu-former-residence_1.png","caption":"张子玉故居"},{"type":"image","url":"/images/archives/zhangziyu-former-residence_2.png","caption":"张子玉故居"},{"type":"image","url":"/images/archives/zhangziyu-former-residence_3.jpeg","caption":"张子玉故居"}]}', 'system', 1784570533785);

