INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-青溪保卫战旧遗址群-1784570533785', 'archive', 'revolution', '[]', 'published', '青溪保卫战旧（遗）址群', '青溪保卫战旧（遗）址群位于河源市紫金县苏区镇青溪村，主要包括：三角炮楼、务本楼、雅正轩、战壕4处。东江苏维埃区域的迅速扩大，使国民党当局大为震惊。2月中旬，当国民党粤归军阀争夺广东统治权的斗争稍微缓和时，以李济深为首的国民党广东当局，立即部署对海陆惠紫革命根据地的军事围剿。2月下旬，东江特委获悉国民党军进攻海陆惠紫的计划后，制定反“围剿”的措施，采用“发动群众的力量，用群众作战的方法来消灭敌人”。', 'normal', '[]', 'version-archive-doc-青溪保卫战旧遗址群-1784570533785-1', 'version-archive-doc-青溪保卫战旧遗址群-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
