-- 青溪乡农会遗址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-青溪乡农会遗址-1784570533785', 'archive', 'government', '[]', 'published', '青溪乡农会遗址', '青溪乡农会遗址位于河源市紫金县苏区镇青溪村上林自然村。1921年5月，彭湃在日本早稻田大学毕业后，回到海丰。1922年7月成立了6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰的炮子乡农民张子玉亲眼看到农会是为农民谋利益的组织，便加入了赤山约农会。1923年1月，张子玉受彭湃派遣，带着2000份农会证返回炮子，组建', 'normal', '[]', 'version-archive-doc-青溪乡农会遗址-1784570533785-1', 'version-archive-doc-青溪乡农会遗址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-青溪乡农会遗址-1784570533785-1', 'content-archive-doc-青溪乡农会遗址-1784570533785', 1, '青溪乡农会遗址', '青溪乡农会遗址位于河源市紫金县苏区镇青溪村上林自然村。1921年5月，彭湃在日本早稻田大学毕业后，回到海丰。1922年7月成立了6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰的炮子乡农民张子玉亲眼看到农会是为农民谋利益的组织，便加入了赤山约农会。1923年1月，张子玉受彭湃派遣，带着2000份农会证返回炮子，组建', '青溪乡农会遗址位于河源市紫金县苏区镇青溪村上林自然村。1921年5月，彭湃在日本早稻田大学毕业后，回到海丰。1922年7月成立了6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰的炮子乡农民张子玉亲眼看到农会是为农民谋利益的组织，便加入了赤山约农会。1923年1月，张子玉受彭湃派遣，带着2000份农会证返回炮子，组建农会组织。3月，紫金县第一个乡农会——炮子乡农会在炮子圩成立。炮子乡农会建立后，发展和壮大农会力量是迫在眉睫的工作任务。于是开展大宣传，向农友高唱《农民苦》歌曲。此外，还有大量客家山歌和民谣进行宣传。', '{"archiveType":"government","type":"government","year":1921,"longitude":115.352,"latitude":23.349,"address":"河源市紫金县苏区镇青溪村上林自然村","coverImage":"/images/archives/qingxi-farmers-association.png","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/qingxi-farmers-association.png","caption":"青溪乡农会遗址"}]}', 'system', 1784570533785);

-- 务德楼战斗旧址
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-务德楼战斗旧址-1784570533785', 'archive', 'revolution', '[]', 'published', '务德楼战斗旧址', '务德楼战斗旧址位于河源市紫金县苏区镇青溪村务本自然村。1928年，由于广东军阀李济深赶走了张发奎，桂系势力伸张，白色政权得到暂时稳定，对红色势力日见强大感到非常恐惧。在帝国主义唆使下，纠集大量兵力，向东江苏区进攻。从老历正月初八起，蔡廷锴一师由五华安流至龙窝，于十一日至紫金的洋头、水墩一路杀来。到琴江青溪时，该乡赤卫队扼守红糖岗交战，乡农会会长钟德英的父亲钟云山及叔父钟云程等困守务德楼，击毙敌二十', 'normal', '[]', 'version-archive-doc-务德楼战斗旧址-1784570533785-1', 'version-archive-doc-务德楼战斗旧址-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-务德楼战斗旧址-1784570533785-1', 'content-archive-doc-务德楼战斗旧址-1784570533785', 1, '务德楼战斗旧址', '务德楼战斗旧址位于河源市紫金县苏区镇青溪村务本自然村。1928年，由于广东军阀李济深赶走了张发奎，桂系势力伸张，白色政权得到暂时稳定，对红色势力日见强大感到非常恐惧。在帝国主义唆使下，纠集大量兵力，向东江苏区进攻。从老历正月初八起，蔡廷锴一师由五华安流至龙窝，于十一日至紫金的洋头、水墩一路杀来。到琴江青溪时，该乡赤卫队扼守红糖岗交战，乡农会会长钟德英的父亲钟云山及叔父钟云程等困守务德楼，击毙敌二十', '务德楼战斗旧址位于河源市紫金县苏区镇青溪村务本自然村。1928年，由于广东军阀李济深赶走了张发奎，桂系势力伸张，白色政权得到暂时稳定，对红色势力日见强大感到非常恐惧。在帝国主义唆使下，纠集大量兵力，向东江苏区进攻。从老历正月初八起，蔡廷锴一师由五华安流至龙窝，于十一日至紫金的洋头、水墩一路杀来。到琴江青溪时，该乡赤卫队扼守红糖岗交战，乡农会会长钟德英的父亲钟云山及叔父钟云程等困守务德楼，击毙敌二十余人。后楼破被捉到青溪塅杀害，房屋被烧。务德楼战斗旧址为典型的客家民居，建筑面积约600平方米。因历经沧桑、年久失修、风雨腐蚀等因素，破旧不堪。', '{"archiveType":"revolution","type":"revolution","year":1928,"longitude":115.348,"latitude":23.352,"address":"河源市紫金县苏区镇青溪村务本自然村","coverImage":"/images/archives/wude-building-battle.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/wude-building-battle.jpeg","caption":"务德楼战斗旧址"}]}', 'system', 1784570533785);

