VALUES ('version-archive-doc-钟定香故居-1784570533785-1', 'content-archive-doc-钟定香故居-1784570533785', 1, '钟定香故居', '钟定香故居位于河源市紫金县苏区镇青溪村上林。钟定香（1898-1932），紫金县苏区青溪村上林人，出生于贫农家庭是当地有名的裁缝师。1923年春，与钟木英组织青溪乡农会，任农会执行委员。自组织农会后，与钟木英积极工作，发展会员，至1924年春，发展了农会会员800多人，并组织农民自卫军30多人。1926年12月，在海丰党训班学习时，加入中国共产党。1927年6月，被选为中共紫金县委委员。7至9月，', '钟定香故居位于河源市紫金县苏区镇青溪村上林。钟定香（1898-1932），紫金县苏区青溪村上林人，出生于贫农家庭是当地有名的裁缝师。1923年春，与钟木英组织青溪乡农会，任农会执行委员。自组织农会后，与钟木英积极工作，发展会员，至1924年春，发展了农会会员800多人，并组织农民自卫军30多人。1926年12月，在海丰党训班学习时，加入中国共产党。1927年6月，被选为中共紫金县委委员。7至9月，率部参与粉碎丘国忠率领民团三次“进剿”炮子的战斗。12月，出任第三区苏维埃政府执行委员兼第三区赤卫大队党代表。1928年2月，国民党军及民团1000多人进攻炮子青溪，组织区、乡赤卫队阻击敌人，激战三天', '{"archiveType":"revolution","type":"revolution","year":1923,"longitude":115.351,"latitude":23.35,"address":"河源市紫金县苏区镇青溪村上林","coverImage":"/images/archives/zhongdingxiang-former-residence_1.png","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_1.png","caption":"钟定香故居"},{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_2.png","caption":"钟定香故居"},{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_3.png","caption":"钟定香故居"},{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_4.png","caption":"钟定香故居"},{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_5.jpeg","caption":"钟定香故居"},{"type":"image","url":"/images/archives/zhongdingxiang-former-residence_6.png","caption":"钟定香故居"}]}', 'system', 1784570533785);

-- 朱豹烈士墓
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-朱豹烈士墓-1784570533785', 'archive', 'revolution', '[]', 'published', '朱豹烈士墓', '朱豹烈士墓位于河源市紫金县苏区镇永坑村。朱豹（1892—1928）领导的坪塘乡农会，任坪塘乡农民自卫队队长。1927年参加紫金县“四二六”武装暴动，后任赤卫大队乡常备队队长。同年加入中国共产党。1928年3月15日，与朱乙一起带领赤卫队23名队员，在公村嶂阻击国民党军“进则”炮子，掩护红军和群众转移。当战至弹尽损绝，农会会员朱凤仙、黄纵、钟亚贤等人牺牲。坚持战斗的朱豹、朱观煌也受伤。接着，朱万牺牲', 'normal', '[]', 'version-archive-doc-朱豹烈士墓-1784570533785-1', 'version-archive-doc-朱豹烈士墓-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-朱豹烈士墓-1784570533785-1', 'content-archive-doc-朱豹烈士墓-1784570533785', 1, '朱豹烈士墓', '朱豹烈士墓位于河源市紫金县苏区镇永坑村。朱豹（1892—1928）领导的坪塘乡农会，任坪塘乡农民自卫队队长。1927年参加紫金县“四二六”武装暴动，后任赤卫大队乡常备队队长。同年加入中国共产党。1928年3月15日，与朱乙一起带领赤卫队23名队员，在公村嶂阻击国民党军“进则”炮子，掩护红军和群众转移。当战至弹尽损绝，农会会员朱凤仙、黄纵、钟亚贤等人牺牲。坚持战斗的朱豹、朱观煌也受伤。接着，朱万牺牲', '朱豹烈士墓位于河源市紫金县苏区镇永坑村。朱豹（1892—1928）领导的坪塘乡农会，任坪塘乡农民自卫队队长。1927年参加紫金县“四二六”武装暴动，后任赤卫大队乡常备队队长。同年加入中国共产党。1928年3月15日，与朱乙一起带领赤卫队23名队员，在公村嶂阻击国民党军“进则”炮子，掩护红军和群众转移。当战至弹尽损绝，农会会员朱凤仙、黄纵、钟亚贤等人牺牲。坚持战斗的朱豹、朱观煌也受伤。接着，朱万牺牲。在此情况下，有的赤卫队员动招。朱豹观此怒火万丈。他望着主峰上迎风招展的7面大旗，率领坚守阵地的全体队员宣誓：“我们要忠于共产党，忠于人民，不动摇，不投降，誓与苏维埃同命运，共存亡，宁愿战死在红旗下甘', '{"archiveType":"revolution","type":"revolution","year":1927,"longitude":115.36,"latitude":23.345,"address":"河源市紫金县苏区镇永坑村","coverImage":"/images/archives/zhubao-martyr-tomb.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zhubao-martyr-tomb.jpeg","caption":"朱豹烈士墓"}]}', 'system', 1784570533785);

-- 朱乙、朱豹烈士纪念碑
INSERT IGNORE INTO `contents` (`id`, `module_key`, `category`, `tags_json`, `status`, `title`, `summary`, `sensitive_level`, `risk_types_json`, `current_version_id`, `published_version_id`, `created_by`, `updated_by`, `created_at`, `updated_at`)
VALUES ('content-archive-doc-朱乙朱豹烈士纪念碑-1784570533785', 'archive', 'revolution', '[]', 'published', '朱乙、朱豹烈士纪念碑', '朱乙、朱豹烈士纪念碑位于河源市紫金县苏区镇永坑村（紫海路边）。朱乙（1864—1928年），紫金县苏区镇永坑村人，1924年任坪塘乡农会会长，1927年加入中国共产党，任坪塘乡苏维埃政府主席，1928年3月率赤卫队在公村嶂阻击国民党军“进剿”炮子，掩护群众安全转移，最后，因弹尽援绝而跳崖，壮烈牺牲。朱豹（1892—1928年），紫金县苏区镇永坑村人，1924年参加农会，任乡农民自卫军队长。1927', 'normal', '[]', 'version-archive-doc-朱乙朱豹烈士纪念碑-1784570533785-1', 'version-archive-doc-朱乙朱豹烈士纪念碑-1784570533785-1', 'system', 'system', 1784570533785, 1784570533785);
INSERT IGNORE INTO `content_versions` (`id`, `content_id`, `version_number`, `title`, `summary`, `body`, `data_json`, `created_by`, `created_at`)
VALUES ('version-archive-doc-朱乙朱豹烈士纪念碑-1784570533785-1', 'content-archive-doc-朱乙朱豹烈士纪念碑-1784570533785', 1, '朱乙、朱豹烈士纪念碑', '朱乙、朱豹烈士纪念碑位于河源市紫金县苏区镇永坑村（紫海路边）。朱乙（1864—1928年），紫金县苏区镇永坑村人，1924年任坪塘乡农会会长，1927年加入中国共产党，任坪塘乡苏维埃政府主席，1928年3月率赤卫队在公村嶂阻击国民党军“进剿”炮子，掩护群众安全转移，最后，因弹尽援绝而跳崖，壮烈牺牲。朱豹（1892—1928年），紫金县苏区镇永坑村人，1924年参加农会，任乡农民自卫军队长。1927', '朱乙、朱豹烈士纪念碑位于河源市紫金县苏区镇永坑村（紫海路边）。朱乙（1864—1928年），紫金县苏区镇永坑村人，1924年任坪塘乡农会会长，1927年加入中国共产党，任坪塘乡苏维埃政府主席，1928年3月率赤卫队在公村嶂阻击国民党军“进剿”炮子，掩护群众安全转移，最后，因弹尽援绝而跳崖，壮烈牺牲。朱豹（1892—1928年），紫金县苏区镇永坑村人，1924年参加农会，任乡农民自卫军队长。1927年参加紫金“四·二六”武装暴动，后任赤卫大队乡常备队队长，同年加入中国共产党。1928年3月，国民党军“进剿”苏区，与朱乙一起率队坚守公村嶂，战至弹尽援绝，英勇就义。为纪念朱乙、朱豹两位烈士，1977', '{"archiveType":"revolution","type":"revolution","year":1928,"longitude":115.361,"latitude":23.344,"address":"河源市紫金县苏区镇永坑村（紫海路边）","coverImage":"/images/archives/zhuyi-zhubao-martyrs-monument.jpeg","historyPeriod":"","relatedPeople":[],"relatedEvents":[],"publishPositions":{"map":true,"list":true,"home":false,"topic":false,"guide":false},"detailBlocks":[],"regionId":"region-suqu","media":[{"type":"image","url":"/images/archives/zhuyi-zhubao-martyrs-monument.jpeg","caption":"朱乙、朱豹烈士纪念碑"}]}', 'system', 1784570533785);

