INSERT IGNORE INTO `archives` (`id`, `title`, `description`, `content`, `type`, `year`, `longitude`, `latitude`, `media_json`, `created_at`, `updated_at`)
SELECT
  '东江独立师指挥部旧址-1784570533785', '东江独立师指挥部旧址', '东江独立师指挥部旧址建于清末，20世纪80年代重建。坐西向东，三间二进，两头横屋。面阔', '东江独立师指挥部旧址建于清末，20世纪80年代重建。坐西向东，三间二进，两头横屋。面阔', 'revolution', 1927, 115.335, 23.365, '[{"url":"/images/archives/dongjiang-independent-division-hq.jpeg","caption":"东江独立师指挥部旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '海陆紫苏维埃政府旧址-1784570533785', '海陆紫苏维埃政府旧址', '海陆紫苏维埃政府旧址原为苏区镇赤溪村宝善楼，建于清朝年间，坐西北向东南，三间二进，二头横屋，总面阔', '海陆紫苏维埃政府旧址原为苏区镇赤溪村宝善楼，建于清朝年间，坐西北向东南，三间二进，二头横屋，总面阔', 'government', 1927, 115.334, 23.366, '[{"url":"/images/archives/hailuzi-soviet-government.jpeg","caption":"海陆紫苏维埃政府旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '油谷坑战斗遗址-1784570533785', '油谷坑战斗遗址', '油谷坑战斗遗址位于河源市紫金县苏区镇赤溪村油谷坑。1933年2月27日，红一团行军至狗头嶂时，与国民党军罗克士残部遭遇。3月27日，红一团移驻黄塘埔美三板桥、塘肚一带，并与紫河特区蓝黄区委书记钟子怀接上了头，得知马毅营和罗克士残部准备进剿埔美，认为周围地形不利于红军作战，随向黄塘曹坑、拔寨转移。马毅营尾随红一团至曹坑。并连续5次发起冲锋，但均被击退。虽大量杀伤国民党军，但红军也伤亡惨重。为减少伤亡', '油谷坑战斗遗址位于河源市紫金县苏区镇赤溪村油谷坑。1933年2月27日，红一团行军至狗头嶂时，与国民党军罗克士残部遭遇。3月27日，红一团移驻黄塘埔美三板桥、塘肚一带，并与紫河特区蓝黄区委书记钟子怀接上了头，得知马毅营和罗克士残部准备进剿埔美，认为周围地形不利于红军作战，随向黄塘曹坑、拔寨转移。马毅营尾随红一团至曹坑。并连续5次发起冲锋，但均被击退。虽大量杀伤国民党军，但红军也伤亡惨重。为减少伤亡，保存力量，东江军委决定兵分两路，一路由东江军委主席朱炎带领到炮子老苏区开展游击战；二路由红一团团长彭桂带领到海陆丰老苏区坚持斗争。4月，朱炎率领30多名红军战士回到炮子赤溪村油谷坑开展游击战，坚持斗', 'revolution', 1933, 115.332, 23.367, '[{"url":"/images/archives/yougukeng-battle.jpeg","caption":"油谷坑战斗遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '朱炎烈士殉难处-1784570533785', '朱炎烈士殉难处', '朱炎烈士殉难处位于河源市紫金县苏区镇赤溪村油谷坑。朱炎（？-1933），湖南人，中国共产党党员。1923年到苏联军校炮科学习。1928年回国，在红四军工作，后随军入广东活动。1931年，受组织委派，到湖惠普边大南山革命根据地开办彭杨军校，任校长，为东江特委培养了一大批军事指挥员。1933年1月，任东江军委主席，参与领导东江革命根据地的武装斗争。不久，由于国民党重兵围困、分割、“进剿”潮惠普边大南山', '朱炎烈士殉难处位于河源市紫金县苏区镇赤溪村油谷坑。朱炎（？-1933），湖南人，中国共产党党员。1923年到苏联军校炮科学习。1928年回国，在红四军工作，后随军入广东活动。1931年，受组织委派，到湖惠普边大南山革命根据地开办彭杨军校，任校长，为东江特委培养了一大批军事指挥员。1933年1月，任东江军委主席，参与领导东江革命根据地的武装斗争。不久，由于国民党重兵围困、分割、“进剿”潮惠普边大南山革命根据地，红军和赤卫队力量削弱。为摆脱强敌围攻，东江军委主席朱炎等率部500多人，从大南山经碣石溪、中洞、三江口、左坑、炮子、洋头，进军乌禽嶂，转战紫河边，准备北上江西与中央红军会师。后在北上途中遭', 'revolution', 1923, 115.332, 23.367, '[{"url":"/images/archives/zhuyan-martyr-shrine.jpeg","caption":"朱炎烈士殉难处"}]', 1784570533785, 1784570533785 UNION ALL
  '缪冠儒烈士纪念碑-1784570533785', '缪冠儒烈士纪念碑', '缪冠儒烈士纪念碑位于河源市紫金县苏区镇龙上村。缪冠儒（1903—1930年），广东五华县周潭乡人。中共党员，黄埔军校学生。1925年2月第一次东征开始后，任紫金县农民自卫军军事教官。6月，指挥农军在南岭竹拐沥全歼陈炯明残部林海山等30多人。10月，任农民自卫军紫金县大队军事教官。1926年10月，率农民自卫军攻打五华登輋温伯洲为首的地主民团及龙窝警署等战斗。1927年4月，率南路农军参加紫金“四二', '缪冠儒烈士纪念碑位于河源市紫金县苏区镇龙上村。缪冠儒（1903—1930年），广东五华县周潭乡人。中共党员，黄埔军校学生。1925年2月第一次东征开始后，任紫金县农民自卫军军事教官。6月，指挥农军在南岭竹拐沥全歼陈炯明残部林海山等30多人。10月，任农民自卫军紫金县大队军事教官。1926年10月，率农民自卫军攻打五华登輋温伯洲为首的地主民团及龙窝警署等战斗。1927年4月，率南路农军参加紫金“四二六”武装暴动。同年秋冬，又率农民自卫军粉碎了紫金县长丘国忠对炮子的三次“进剿”的战斗。10月，任中国工农革命军紫金县大队第二大队大队长。1928年1月，率队配合红二师等联合攻打龙窝区署和民团。后又率部', 'revolution', 1930, 115.355, 23.375, '[{"url":"/images/archives/miaoguanru-martyr-monument.jpeg","caption":"缪冠儒烈士纪念碑"}]', 1784570533785, 1784570533785 UNION ALL
  '红军兵工厂旧址-1784570533785', '红军兵工厂旧址', '红军兵工厂旧址位于苏区镇炮子村，是一座民房，建于清代，坐北向南，二间二进，右侧横屋，左侧只建横屋厅，檩条山墙结构，硬山顶，砖墙，石基脚，建筑面积110多平方米。2009年4月被紫金县人民政府公布为紫金县文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为广东省爱国主义教育基地。', '红军兵工厂旧址位于苏区镇炮子村，是一座民房，建于清代，坐北向南，二间二进，右侧横屋，左侧只建横屋厅，檩条山墙结构，硬山顶，砖墙，石基脚，建筑面积110多平方米。2009年4月被紫金县人民政府公布为紫金县文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为广东省爱国主义教育基地。', 'revolution', 2009, 115.3365, 23.3575, '[{"url":"/images/archives/red-army-arsenal.jpeg","caption":"红军兵工厂旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '红军号兵训练所旧址-1784570533785', '红军号兵训练所旧址', '红军号兵训练所旧址位于苏区镇炮子村老寨岗，是一座民房，建于清代，坐西北向东南，三间二进，占地面积108平方米，檩条山墙结构，硬山顶，灰瓦。2009年被紫金县人民政府公布为紫金县文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为广东省爱国主义教育基地。', '红军号兵训练所旧址位于苏区镇炮子村老寨岗，是一座民房，建于清代，坐西北向东南，三间二进，占地面积108平方米，檩条山墙结构，硬山顶，灰瓦。2009年被紫金县人民政府公布为紫金县文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为广东省爱国主义教育基地。', 'revolution', 2009, 115.338, 23.359, '[{"url":"/images/archives/red-army-bugler-training.jpeg","caption":"红军号兵训练所旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '红二师官兵操练遗址-1784570533785', '红二师官兵操练遗址', '位于紫金县苏区镇炮子村委会右后侧。原为一片荒地，是当年红二师操练的地方。1956年，紫金县人民委员会根据中央慰问团指示修建此亭，以志纪念。2008年重建，全亭建筑面积13平方米，6条红色水泥圆柱，高7米，边长', '位于紫金县苏区镇炮子村委会右后侧。原为一片荒地，是当年红二师操练的地方。1956年，紫金县人民委员会根据中央慰问团指示修建此亭，以志纪念。2008年重建，全亭建筑面积13平方米，6条红色水泥圆柱，高7米，边长', 'revolution', 1956, 115.342, 23.3625, '[{"url":"/images/archives/red-second-division-drill.jpeg","caption":"红二师官兵操练遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '红六军四十九团团部旧址-1784570533785', '红六军四十九团团部旧址', '红六军四十九团团部旧址和中共紫河特区委、共青团紫河特区委、紫河游击队队部成立旧址位于苏区镇炮子村红旗小组明德楼。 1929年3月，蒋桂战争爆发后，很快桂系为蒋介石所败，桂系李济深在广东的统治也为蒋系陈济棠所取代，接着发生蒋、阎、冯军阀混战。4月，海陆丰的驻军十六师全部调走，海陆丰的反动势力顿显薄弱，反动派非常恐慌。9月，海陆惠紫特委在省委领导下，认识到革命高潮已经到来，便不失时机地决定建立红军。1', '红六军四十九团团部旧址和中共紫河特区委、共青团紫河特区委、紫河游击队队部成立旧址位于苏区镇炮子村红旗小组明德楼。 1929年3月，蒋桂战争爆发后，很快桂系为蒋介石所败，桂系李济深在广东的统治也为蒋系陈济棠所取代，接着发生蒋、阎、冯军阀混战。4月，海陆丰的驻军十六师全部调走，海陆丰的反动势力顿显薄弱，反动派非常恐慌。9月，海陆惠紫特委在省委领导下，认识到革命高潮已经到来，便不失时机地决定建立红军。10月初，海陆惠紫特委在黄羌朝面山蔡背窝举行军事会议。会后，在朝面山大路下村召开大会，宣告中国工农红军第六军第十七师四十九团成立。不久，四十九团团部迁到苏区镇炮子村红旗小组明德楼。虽然当时只有100多人', 'revolution', 1929, 115.342, 23.361, '[{"url":"/images/archives/red-49th-regiment-hq.jpeg","caption":"红六军四十九团团部旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '龙炮区联队队部旧址-1784570533785', '龙炮区联队队部旧址', '龙炮区联队队部旧址位于苏区镇炮子村大湾温氏老屋内，原建筑建于清代，坐西北向东南，五间二进，两头横屋，总面阔', '龙炮区联队队部旧址位于苏区镇炮子村大湾温氏老屋内，原建筑建于清代，坐西北向东南，五间二进，两头横屋，总面阔', 'government', 1927, 115.34, 23.36, '[{"url":"/images/archives/longpao-district-union-hq_1.png","caption":"龙炮区联队队部旧址"},{"url":"/images/archives/longpao-district-union-hq_2.jpeg","caption":"龙炮区联队队部旧址"},{"url":"/images/archives/longpao-district-union-hq_3.jpeg","caption":"龙炮区联队队部旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '炮子乡农会旧址-1784570533785', '炮子乡农会旧址', '炮子乡农会、紫金县总农会旧址建于民国期间，坐北向南，三间二进二层，檩条山墙结构。硬山顶，平脊，灰瓦，砖墙，石基脚。占地面积约65平方米。1923年1月，苏区山子背人张子玉受彭湃指派，带着2000份农会证返回苏区，3月成立了炮子乡农会，张子玉为会长，钟乐善、黄培先为副会长，隶属海丰总农会领导，从此点燃了紫金农民运动的火种。同年7月，紫金各乡农民代表在此集会，成立紫金县总农会和龙窝区农会。炮子乡农会、', '炮子乡农会、紫金县总农会旧址建于民国期间，坐北向南，三间二进二层，檩条山墙结构。硬山顶，平脊，灰瓦，砖墙，石基脚。占地面积约65平方米。1923年1月，苏区山子背人张子玉受彭湃指派，带着2000份农会证返回苏区，3月成立了炮子乡农会，张子玉为会长，钟乐善、黄培先为副会长，隶属海丰总农会领导，从此点燃了紫金农民运动的火种。同年7月，紫金各乡农民代表在此集会，成立紫金县总农会和龙窝区农会。炮子乡农会、紫金县总农会旧址于2009年4月被紫金县人民政府公布为紫金县文物保护单位；2011年3月被河源市人民政府公布为河源市重点文物保护单位；2011年6月被广东省精神文明建设委员会、中共广东省委宣传部公布为', 'government', 1923, 115.3445, 23.3605, '[]', 1784570533785, 1784570533785 UNION ALL
  '战壕遗址-1784570533785', '战壕遗址', '战壕遗址位于河源市紫金县苏区镇炮子村伯公坳。1928年3月，国民党第十一军某部3000余人，由五华县安流出发，经紫金洋头、慎田进剿龙炮苏区。中共紫金县委、县苏维埃政府与红二师研究后，决定组织正规军、地方团队和区、乡赤卫队进行保卫苏维埃的战斗。苏区 军民紧张地在各战略要地构筑防御阵地，其中在伯公坳挖战壕，修掩体，誓死保卫苏区。现存战壕东西走向，长56米，宽', '战壕遗址位于河源市紫金县苏区镇炮子村伯公坳。1928年3月，国民党第十一军某部3000余人，由五华县安流出发，经紫金洋头、慎田进剿龙炮苏区。中共紫金县委、县苏维埃政府与红二师研究后，决定组织正规军、地方团队和区、乡赤卫队进行保卫苏维埃的战斗。苏区 军民紧张地在各战略要地构筑防御阵地，其中在伯公坳挖战壕，修掩体，誓死保卫苏区。现存战壕东西走向，长56米，宽', 'revolution', 1928, 115.333, 23.3585, '[{"url":"/images/archives/trench-site_1.jpeg","caption":"战壕遗址"},{"url":"/images/archives/trench-site_2.jpeg","caption":"战壕遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '张子玉烈士纪念碑-1784570533785', '张子玉烈士纪念碑', '张子玉烈士纪念碑位于紫金县苏区镇炮子村锡山小学操场边。张子玉（1899—1928年），1923年由他发起成立紫金县第一个农会——炮子乡农会并任会长，1925年加入中国共产党，1927年组织紫金南路农民自卫军参加“四·二六”暴动，1928年3月在陆丰罗畲突围中与部队失去联系，回炮子召集人员，迅速恢复苏区革命斗争，指挥赤卫队员坚持游击活动，同年8月因叛徒出卖被捕，10月被杀害，时年29岁。1977年，', '张子玉烈士纪念碑位于紫金县苏区镇炮子村锡山小学操场边。张子玉（1899—1928年），1923年由他发起成立紫金县第一个农会——炮子乡农会并任会长，1925年加入中国共产党，1927年组织紫金南路农民自卫军参加“四·二六”暴动，1928年3月在陆丰罗畲突围中与部队失去联系，回炮子召集人员，迅速恢复苏区革命斗争，指挥赤卫队员坚持游击活动，同年8月因叛徒出卖被捕，10月被杀害，时年29岁。1977年，紫金县人民政府兴建张子玉烈士纪念碑一座，以彰显张子玉烈士的丰功伟绩，告慰英魂。2011年重建，碑身青砖垒砌，外贴白瓷片，高', 'revolution', 1928, 115.339, 23.356, '[{"url":"/images/archives/zhangziyu-martyr-monument_1.jpeg","caption":"张子玉烈士纪念碑"},{"url":"/images/archives/zhangziyu-martyr-monument_2.jpeg","caption":"张子玉烈士纪念碑"}]', 1784570533785, 1784570533785 UNION ALL
  '中国工农革命军第二师师部旧址-1784570533785', '中国工农革命军第二师师部旧址', '位于苏区镇炮子村，建于清末，建筑面积300多平方米。1927年10月，撤退到海陆惠紫的“八一”南昌起义部分队伍，在中共东江特委的领导下，整编为中国工农革命军第二师（红二师）。同月，红二师进驻紫金，师部和党代表办公地设在炮子福星楼。师长董朗、党代表颜昌颐，在这里指挥武装斗争，给反革命武装以沉重的打击。1928年3月，因国民党反动派派重兵“围剿”，红二师与赤卫队一起保卫紫金县委、紫金县苏维埃政府和人民', '位于苏区镇炮子村，建于清末，建筑面积300多平方米。1927年10月，撤退到海陆惠紫的“八一”南昌起义部分队伍，在中共东江特委的领导下，整编为中国工农革命军第二师（红二师）。同月，红二师进驻紫金，师部和党代表办公地设在炮子福星楼。师长董朗、党代表颜昌颐，在这里指挥武装斗争，给反革命武装以沉重的打击。1928年3月，因国民党反动派派重兵“围剿”，红二师与赤卫队一起保卫紫金县委、紫金县苏维埃政府和人民群众撤出炮子，安全转移。后在海、陆、惠、紫、五等县坚持开展游击战争，多次粉碎国民党反动派的“围剿”，为保卫革命根据地作出了巨大贡献。1977年1月被紫金县人民政府公布为紫金县重点文物保护单位；2011', 'revolution', 1927, 115.341, 23.3615, '[{"url":"/images/archives/red-second-division-hq.jpeg","caption":"中国工农革命军第二师师部旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '红四师第十团开会遗址-1784570533785', '红四师第十团开会遗址', '位于苏区镇炮子村耕头墩，俗称红军坪，占地面积100多平方米。1928年红四师第十团曾在此召开全体指战员大会，徐向前作了重要讲话。1977年在遗址中心立碑一座，坐东北向西南，高', '位于苏区镇炮子村耕头墩，俗称红军坪，占地面积100多平方米。1928年红四师第十团曾在此召开全体指战员大会，徐向前作了重要讲话。1977年在遗址中心立碑一座，坐东北向西南，高', 'revolution', 1928, 115.337, 23.363, '[{"url":"/images/archives/red-fourth-division-10th-regiment.jpeg","caption":"红四师第十团开会遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '钟一朋烈士纪念碑-1784570533785', '钟一朋烈士纪念碑', '钟一朋烈士纪念碑位于苏区镇炮子村。钟一朋（1900—1931年），紫金苏区炮子人，1923年4月被选为炮子乡乡农会副会长兼乡农军自卫军队长，1925年12月加入中国共产党，1928年春调任工农革命军紫金第二大队副大队长，1931年因叛徒告密被捕，后被杀害。纪念碑建于1976年，坐北向南，方顶，碑高2米，宽', '钟一朋烈士纪念碑位于苏区镇炮子村。钟一朋（1900—1931年），紫金苏区炮子人，1923年4月被选为炮子乡乡农会副会长兼乡农军自卫军队长，1925年12月加入中国共产党，1928年春调任工农革命军紫金第二大队副大队长，1931年因叛徒告密被捕，后被杀害。纪念碑建于1976年，坐北向南，方顶，碑高2米，宽', 'revolution', 1931, 115.34, 23.358, '[{"url":"/images/archives/zhongyipeng-martyr-monument.jpeg","caption":"钟一朋烈士纪念碑"}]', 1784570533785, 1784570533785 UNION ALL
  '紫金县老苏区革命烈士纪念堂-1784570533785', '紫金县老苏区革命烈士纪念堂', '紫金县老苏区革命烈士纪念堂位于河源市紫金县苏区镇炮子村，1927年4月 26日，在东江特委的领导下，在刘琴西等人的直接指挥下，紫金人民成功进行了“四二六” 武装暴动，占领了紫金县城。5月1日，成立了紫金县人民政府，刘琴西为主席，戴耀田为副主席，同时成立了以刘琴西为总指挥的紫金县工农革命军总指挥部。5月8日，紫金县党政军机关转移到紫金南部地区，在炮子建立革命根据地，开展土地革命斗争。此后，中共紫金县', '紫金县老苏区革命烈士纪念堂位于河源市紫金县苏区镇炮子村，1927年4月 26日，在东江特委的领导下，在刘琴西等人的直接指挥下，紫金人民成功进行了“四二六” 武装暴动，占领了紫金县城。5月1日，成立了紫金县人民政府，刘琴西为主席，戴耀田为副主席，同时成立了以刘琴西为总指挥的紫金县工农革命军总指挥部。5月8日，紫金县党政军机关转移到紫金南部地区，在炮子建立革命根据地，开展土地革命斗争。此后，中共紫金县委、县苏维埃政府在苏区领导紫金人民进行轰轰烈烈的土地革命、根据地建设和武装斗争，经历了炮子三次反“围剿”、苏区保卫战等众多惨烈的战斗。苏区人民为建设和保卫革命根据地作出了巨大贡献和重大牺牲。1963年', 'revolution', 1927, 115.342, 23.362, '[{"url":"/images/archives/zijin-old-suqu-martyrs-memorial_1.jpeg","caption":"紫金县老苏区革命烈士纪念堂"},{"url":"/images/archives/zijin-old-suqu-martyrs-memorial_2.jpeg","caption":"紫金县老苏区革命烈士纪念堂"}]', 1784570533785, 1784570533785 UNION ALL
  '红二四师联合公审大会遗址-1784570533785', '红二、四师联合公审大会遗址', '红二、四师联合公审大会遗址位于河源市紫金县苏区镇炮子村。1927年12月，撤向东江地区的广州起义部队1000多人，在县改编为中国工农革命军第四师（简称红四师），叶镛为师长，宋湘涛为副师长，袁裕为师参谋长。1928年1月，红四师智取紫金县城，活捉国民党紫金县长东丘国忠等17名反动头子。3日，在湖子仓研究决定于5日召开公审大会，处决丘国忠等17名反动分子。5日上午，赤卫队和红军战士把丘国忠等反动头子押', '红二、四师联合公审大会遗址位于河源市紫金县苏区镇炮子村。1927年12月，撤向东江地区的广州起义部队1000多人，在县改编为中国工农革命军第四师（简称红四师），叶镛为师长，宋湘涛为副师长，袁裕为师参谋长。1928年1月，红四师智取紫金县城，活捉国民党紫金县长东丘国忠等17名反动头子。3日，在湖子仓研究决定于5日召开公审大会，处决丘国忠等17名反动分子。5日上午，赤卫队和红军战士把丘国忠等反动头子押赴刑场，由钟佑廷、钟初发、温冠雄等用马刀处决这批反动分子。群众振臂欢呼，扬眉吐气，都说苏维埃政权够气派，工农红军确威风，炮子革命根据地沉浸在一片欢乐之中。遗址现为苏区中学操场。', 'revolution', 1927, 115.338, 23.36, '[{"url":"/images/archives/red-2nd-4th-division-trial.png","caption":"红二、四师联合公审大会遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '炮子农民自卫队队部遗址-1784570533785', '炮子农民自卫队队部遗址', '位于河源市紫金县苏区镇炮子村。1923年1月，陈炯明叛变孙中山民主革命盘踞东江后，豢养了一批亲信，为非作歹。一次，其部在紫金龙窝、炮子等地横行霸道，打家劫舍，抢走钟善道、钟彩文的马。族中头领钟乐善，凭借拥有10多人枪的队伍，下令抄小路在赤溪截击，打败了陈炯明部。陈炯明得知后，即下令“剿平”炮子。民众在危急之时，一筹莫展。张子玉顺水推舟，说明要粉碎陈炯明“剿平”炮子的阴谋，必须在彭海的领导下，成立农', '位于河源市紫金县苏区镇炮子村。1923年1月，陈炯明叛变孙中山民主革命盘踞东江后，豢养了一批亲信，为非作歹。一次，其部在紫金龙窝、炮子等地横行霸道，打家劫舍，抢走钟善道、钟彩文的马。族中头领钟乐善，凭借拥有10多人枪的队伍，下令抄小路在赤溪截击，打败了陈炯明部。陈炯明得知后，即下令“剿平”炮子。民众在危急之时，一筹莫展。张子玉顺水推舟，说明要粉碎陈炯明“剿平”炮子的阴谋，必须在彭海的领导下，成立农会，组织农民武装。不久，炮子乡农会成立，张子玉当选为会长，钟乐善、黄培先为副会长。为粉碎陈炯明“剿平” 炮子的阴谋，钟乐善提出族中的武装由炮子乡农会统一指挥，并星夜袭击炮子通往高潭的石门沥黄亚品、黄萌', 'revolution', 1923, 115.339, 23.361, '[{"url":"/images/archives/paozi-peasant-selfdefense-hq.png","caption":"炮子农民自卫队队部遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '洋磜反围剿战斗遗址-1784570533785', '洋磜反“围剿”战斗遗址', '洋磜反“围剿”战斗遗址位于河源市紫金县苏区镇炮子村锡山洋磜。1931年10月，南岭反动分子、五县联防剿共主任钟汉平率南岭、登峯、大茂、禾多布、黄布、小北等48个乡的民团，并勾结国民党军驻炮子叶吉辉一个营、驻永坑一个营、土匪叶添等杂牌军共3000余人从锡山崬、油谷坑、唱歌崬等地登山，围剿洋磜，企图消灭隐藏在洋磜坚持游击战争的红十一军军事部，海陆紫县苏，紫金县委、县苏领导机关。在敌强我弱的情况下，古大', '洋磜反“围剿”战斗遗址位于河源市紫金县苏区镇炮子村锡山洋磜。1931年10月，南岭反动分子、五县联防剿共主任钟汉平率南岭、登峯、大茂、禾多布、黄布、小北等48个乡的民团，并勾结国民党军驻炮子叶吉辉一个营、驻永坑一个营、土匪叶添等杂牌军共3000余人从锡山崬、油谷坑、唱歌崬等地登山，围剿洋磜，企图消灭隐藏在洋磜坚持游击战争的红十一军军事部，海陆紫县苏，紫金县委、县苏领导机关。在敌强我弱的情况下，古大存、古宜权召集海陆紫县苏主席团钟一强、林潭吉，紫金县委、龙炮区联队领导人戴耀田、缪冠儒等紧急会商并制定了反“围剿”的作战方案。永坑乡赤卫队70余人，在中队长高镜率领下，奋起迎战。梅兴乡赤卫队20余人，', 'revolution', 1931, 115.344, 23.355, '[{"url":"/images/archives/yangqi-anti-encirclement.png","caption":"洋磜反“围剿”战斗遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '洋磜会师遗址-1784570533785', '洋磜会师遗址', '位于苏区镇炮子村锡山，在锡山崬、唱歌崬、峰的夹谷中，西连炮子的油谷坑，峭壁挺立，地势险要。山谷中有几座房屋，住着十来户人家。从1928年革命低潮以来，县委、县苏的领导机关经常来这里隐蔽，继续领导革命。1931年6月，海陆紫县苏、紫金县委、县苏领导机关又从风隆山搬到这里。八乡山是东江地区的重要革命根据地之一。1929年秋后，中共东江特委迁驻八乡山。八乡山便成为东江革命根据地的指挥中心。1931年1月', '位于苏区镇炮子村锡山，在锡山崬、唱歌崬、峰的夹谷中，西连炮子的油谷坑，峭壁挺立，地势险要。山谷中有几座房屋，住着十来户人家。从1928年革命低潮以来，县委、县苏的领导机关经常来这里隐蔽，继续领导革命。1931年6月，海陆紫县苏、紫金县委、县苏领导机关又从风隆山搬到这里。八乡山是东江地区的重要革命根据地之一。1929年秋后，中共东江特委迁驻八乡山。八乡山便成为东江革命根据地的指挥中心。1931年1月，为配合蒋介石对中央根据地发起的第二次“围剿”，陈济棠调该军第二独立旅张瑞贵部到东江，纠集五华、丰顺、揭阳三县警卫队、民团、大规模向八乡山根据地发起“围剿”。面对恶劣环境，为保存实力，牵制敌人，红十一', 'revolution', 1928, 115.345, 23.354, '[{"url":"/images/archives/yangqi-joining-forces.jpeg","caption":"洋磜会师遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '云谭村农会旧址-1784570533785', '云谭村农会旧址', '位于河源市紫金县苏区镇炮子村山子背。1922年7月，彭湃领导成立6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰挑担度日的炮子村山子背农民张子玉，亲眼看到农会是为农民谋利益的组织，毅然参加了赤山约农会。彭湃得知张子玉是紫金县人，便在得趣书院接见了张子玉。1923年1月，张子玉受彭湃的委托，带着2000份农会证返回家', '位于河源市紫金县苏区镇炮子村山子背。1922年7月，彭湃领导成立6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰挑担度日的炮子村山子背农民张子玉，亲眼看到农会是为农民谋利益的组织，毅然参加了赤山约农会。彭湃得知张子玉是紫金县人，便在得趣书院接见了张子玉。1923年1月，张子玉受彭湃的委托，带着2000份农会证返回家乡，组建农会组织。张子玉回到家乡后，考虑到自己地位低下，难于开展工作，便向族中有威信的堂叔张大经讨教。张大经对张子玉的行动表示支持。于是商定在春节祭祖时，与族长商议。农历正月十四日（族人规定的“上丁日', 'revolution', 1922, 115.336, 23.357, '[{"url":"/images/archives/yuntan-farmers-association.jpeg","caption":"云谭村农会旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '张子玉故居-1784570533785', '张子玉故居', '张子玉故居，位于河源市紫金县苏区镇炮子村山子背。张子玉（1899-1928），原名连科，出生于紫金县苏区镇炮子村一个雇农家庭。1922年逃难到海丰参加海丰县农会组织。后受彭湃派遣回乡发展农会。1923年农历正月十四日，发动组建紫金县第一个村农会－－云潭村农会。3月，发动建立紫金县第一个乡农会－－炮子乡农会，任会长。7月，协助钟一强等在炮子召开各乡农民代表会，成立紫金县总农会和龙窝区农会，并任龙窝区', '张子玉故居，位于河源市紫金县苏区镇炮子村山子背。张子玉（1899-1928），原名连科，出生于紫金县苏区镇炮子村一个雇农家庭。1922年逃难到海丰参加海丰县农会组织。后受彭湃派遣回乡发展农会。1923年农历正月十四日，发动组建紫金县第一个村农会－－云潭村农会。3月，发动建立紫金县第一个乡农会－－炮子乡农会，任会长。7月，协助钟一强等在炮子召开各乡农民代表会，成立紫金县总农会和龙窝区农会，并任龙窝区农会会长。不久，在龙窝区组建农民自卫军。1925年，紫金县总农会改称紫金县农民协会，任第三区农民协会会长。同年加入中国共产党。1927年，参与组织南路农民自卫军参加紫金县“四二六”武装暴动，12月，把', 'revolution', 1922, 115.339, 23.356, '[{"url":"/images/archives/zhangziyu-former-residence_1.png","caption":"张子玉故居"},{"url":"/images/archives/zhangziyu-former-residence_2.png","caption":"张子玉故居"},{"url":"/images/archives/zhangziyu-former-residence_3.jpeg","caption":"张子玉故居"}]', 1784570533785, 1784570533785 UNION ALL
  '青溪保卫战旧遗址群-1784570533785', '青溪保卫战旧（遗）址群', '青溪保卫战旧（遗）址群位于河源市紫金县苏区镇青溪村，主要包括：三角炮楼、务本楼、雅正轩、战壕4处。东江苏维埃区域的迅速扩大，使国民党当局大为震惊。2月中旬，当国民党粤归军阀争夺广东统治权的斗争稍微缓和时，以李济深为首的国民党广东当局，立即部署对海陆惠紫革命根据地的军事围剿。2月下旬，东江特委获悉国民党军进攻海陆惠紫的计划后，制定反“围剿”的措施，采用“发动群众的力量，用群众作战的方法来消灭敌人”。', '青溪保卫战旧（遗）址群位于河源市紫金县苏区镇青溪村，主要包括：三角炮楼、务本楼、雅正轩、战壕4处。东江苏维埃区域的迅速扩大，使国民党当局大为震惊。2月中旬，当国民党粤归军阀争夺广东统治权的斗争稍微缓和时，以李济深为首的国民党广东当局，立即部署对海陆惠紫革命根据地的军事围剿。2月下旬，东江特委获悉国民党军进攻海陆惠紫的计划后，制定反“围剿”的措施，采用“发动群众的力量，用群众作战的方法来消灭敌人”。东江特委还发表宣言，指出目前东江时局非常严重，号召东江工农群众起来武装保卫苏维埃政权。接着，中共东江特委对海陆惠紫苏区反“围剿”工作作了部署。誓死保卫苏维埃政权。3月1日，国民党第十一军蔡廷锴部300', 'revolution', 1978, 115.35, 23.35, '[{"url":"/images/archives/qingxi-defense-battle.jpeg","caption":"青溪保卫战旧（遗）址群"}]', 1784570533785, 1784570533785 UNION ALL
  '青溪乡农会遗址-1784570533785', '青溪乡农会遗址', '青溪乡农会遗址位于河源市紫金县苏区镇青溪村上林自然村。1921年5月，彭湃在日本早稻田大学毕业后，回到海丰。1922年7月成立了6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰的炮子乡农民张子玉亲眼看到农会是为农民谋利益的组织，便加入了赤山约农会。1923年1月，张子玉受彭湃派遣，带着2000份农会证返回炮子，组建', '青溪乡农会遗址位于河源市紫金县苏区镇青溪村上林自然村。1921年5月，彭湃在日本早稻田大学毕业后，回到海丰。1922年7月成立了6人农会，10月25日又成立了赤山约农会。1923年元旦，海丰县召开了全县农民代表大会，正式成立了海丰县农会。1922年，逃难到海丰的炮子乡农民张子玉亲眼看到农会是为农民谋利益的组织，便加入了赤山约农会。1923年1月，张子玉受彭湃派遣，带着2000份农会证返回炮子，组建农会组织。3月，紫金县第一个乡农会——炮子乡农会在炮子圩成立。炮子乡农会建立后，发展和壮大农会力量是迫在眉睫的工作任务。于是开展大宣传，向农友高唱《农民苦》歌曲。此外，还有大量客家山歌和民谣进行宣传。', 'government', 1921, 115.352, 23.349, '[{"url":"/images/archives/qingxi-farmers-association.png","caption":"青溪乡农会遗址"}]', 1784570533785, 1784570533785 UNION ALL
  '务德楼战斗旧址-1784570533785', '务德楼战斗旧址', '务德楼战斗旧址位于河源市紫金县苏区镇青溪村务本自然村。1928年，由于广东军阀李济深赶走了张发奎，桂系势力伸张，白色政权得到暂时稳定，对红色势力日见强大感到非常恐惧。在帝国主义唆使下，纠集大量兵力，向东江苏区进攻。从老历正月初八起，蔡廷锴一师由五华安流至龙窝，于十一日至紫金的洋头、水墩一路杀来。到琴江青溪时，该乡赤卫队扼守红糖岗交战，乡农会会长钟德英的父亲钟云山及叔父钟云程等困守务德楼，击毙敌二十', '务德楼战斗旧址位于河源市紫金县苏区镇青溪村务本自然村。1928年，由于广东军阀李济深赶走了张发奎，桂系势力伸张，白色政权得到暂时稳定，对红色势力日见强大感到非常恐惧。在帝国主义唆使下，纠集大量兵力，向东江苏区进攻。从老历正月初八起，蔡廷锴一师由五华安流至龙窝，于十一日至紫金的洋头、水墩一路杀来。到琴江青溪时，该乡赤卫队扼守红糖岗交战，乡农会会长钟德英的父亲钟云山及叔父钟云程等困守务德楼，击毙敌二十余人。后楼破被捉到青溪塅杀害，房屋被烧。务德楼战斗旧址为典型的客家民居，建筑面积约600平方米。因历经沧桑、年久失修、风雨腐蚀等因素，破旧不堪。', 'revolution', 1928, 115.348, 23.352, '[{"url":"/images/archives/wude-building-battle.jpeg","caption":"务德楼战斗旧址"}]', 1784570533785, 1784570533785 UNION ALL
  '钟定香故居-1784570533785', '钟定香故居', '钟定香故居位于河源市紫金县苏区镇青溪村上林。钟定香（1898-1932），紫金县苏区青溪村上林人，出生于贫农家庭是当地有名的裁缝师。1923年春，与钟木英组织青溪乡农会，任农会执行委员。自组织农会后，与钟木英积极工作，发展会员，至1924年春，发展了农会会员800多人，并组织农民自卫军30多人。1926年12月，在海丰党训班学习时，加入中国共产党。1927年6月，被选为中共紫金县委委员。7至9月，', '钟定香故居位于河源市紫金县苏区镇青溪村上林。钟定香（1898-1932），紫金县苏区青溪村上林人，出生于贫农家庭是当地有名的裁缝师。1923年春，与钟木英组织青溪乡农会，任农会执行委员。自组织农会后，与钟木英积极工作，发展会员，至1924年春，发展了农会会员800多人，并组织农民自卫军30多人。1926年12月，在海丰党训班学习时，加入中国共产党。1927年6月，被选为中共紫金县委委员。7至9月，率部参与粉碎丘国忠率领民团三次“进剿”炮子的战斗。12月，出任第三区苏维埃政府执行委员兼第三区赤卫大队党代表。1928年2月，国民党军及民团1000多人进攻炮子青溪，组织区、乡赤卫队阻击敌人，激战三天', 'revolution', 1923, 115.351, 23.35, '[{"url":"/images/archives/zhongdingxiang-former-residence_1.png","caption":"钟定香故居"},{"url":"/images/archives/zhongdingxiang-former-residence_2.png","caption":"钟定香故居"},{"url":"/images/archives/zhongdingxiang-former-residence_3.png","caption":"钟定香故居"},{"url":"/images/archives/zhongdingxiang-former-residence_4.png","caption":"钟定香故居"},{"url":"/images/archives/zhongdingxiang-former-residence_5.jpeg","caption":"钟定香故居"},{"url":"/images/archives/zhongdingxiang-former-residence_6.png","caption":"钟定香故居"}]', 1784570533785, 1784570533785 UNION ALL
  '朱豹烈士墓-1784570533785', '朱豹烈士墓', '朱豹烈士墓位于河源市紫金县苏区镇永坑村。朱豹（1892—1928）领导的坪塘乡农会，任坪塘乡农民自卫队队长。1927年参加紫金县“四二六”武装暴动，后任赤卫大队乡常备队队长。同年加入中国共产党。1928年3月15日，与朱乙一起带领赤卫队23名队员，在公村嶂阻击国民党军“进则”炮子，掩护红军和群众转移。当战至弹尽损绝，农会会员朱凤仙、黄纵、钟亚贤等人牺牲。坚持战斗的朱豹、朱观煌也受伤。接着，朱万牺牲', '朱豹烈士墓位于河源市紫金县苏区镇永坑村。朱豹（1892—1928）领导的坪塘乡农会，任坪塘乡农民自卫队队长。1927年参加紫金县“四二六”武装暴动，后任赤卫大队乡常备队队长。同年加入中国共产党。1928年3月15日，与朱乙一起带领赤卫队23名队员，在公村嶂阻击国民党军“进则”炮子，掩护红军和群众转移。当战至弹尽损绝，农会会员朱凤仙、黄纵、钟亚贤等人牺牲。坚持战斗的朱豹、朱观煌也受伤。接着，朱万牺牲。在此情况下，有的赤卫队员动招。朱豹观此怒火万丈。他望着主峰上迎风招展的7面大旗，率领坚守阵地的全体队员宣誓：“我们要忠于共产党，忠于人民，不动摇，不投降，誓与苏维埃同命运，共存亡，宁愿战死在红旗下甘', 'revolution', 1927, 115.36, 23.345, '[{"url":"/images/archives/zhubao-martyr-tomb.jpeg","caption":"朱豹烈士墓"}]', 1784570533785, 1784570533785 UNION ALL
  '朱乙朱豹烈士纪念碑-1784570533785', '朱乙、朱豹烈士纪念碑', '朱乙、朱豹烈士纪念碑位于河源市紫金县苏区镇永坑村（紫海路边）。朱乙（1864—1928年），紫金县苏区镇永坑村人，1924年任坪塘乡农会会长，1927年加入中国共产党，任坪塘乡苏维埃政府主席，1928年3月率赤卫队在公村嶂阻击国民党军“进剿”炮子，掩护群众安全转移，最后，因弹尽援绝而跳崖，壮烈牺牲。朱豹（1892—1928年），紫金县苏区镇永坑村人，1924年参加农会，任乡农民自卫军队长。1927', '朱乙、朱豹烈士纪念碑位于河源市紫金县苏区镇永坑村（紫海路边）。朱乙（1864—1928年），紫金县苏区镇永坑村人，1924年任坪塘乡农会会长，1927年加入中国共产党，任坪塘乡苏维埃政府主席，1928年3月率赤卫队在公村嶂阻击国民党军“进剿”炮子，掩护群众安全转移，最后，因弹尽援绝而跳崖，壮烈牺牲。朱豹（1892—1928年），紫金县苏区镇永坑村人，1924年参加农会，任乡农民自卫军队长。1927年参加紫金“四·二六”武装暴动，后任赤卫大队乡常备队队长，同年加入中国共产党。1928年3月，国民党军“进剿”苏区，与朱乙一起率队坚守公村嶂，战至弹尽援绝，英勇就义。为纪念朱乙、朱豹两位烈士，1977', 'revolution', 1928, 115.361, 23.344, '[{"url":"/images/archives/zhuyi-zhubao-martyrs-monument.jpeg","caption":"朱乙、朱豹烈士纪念碑"}]', 1784570533785, 1784570533785;

